import json
for name in ["contracts-scopes","arch-scope","arch-chains","p2exec","tm-auth","tm-diag","tm-new","doctor","d7","d8","d16","d17"]:
    p=f"/tmp/p28-{name}.txt"
    data=json.load(open(p))
    print("="*20, name, "keys", data.keys())
    d=data.get("data",{})
    if isinstance(d, dict):
        print(" data keys", d.keys())
        doc=d.get("doc")
        if isinstance(doc, dict):
            print(" doc keys", list(doc.keys())[:40])
            # print section-like
            for k in ("body","content","sections","text","markdown"):
                if k in doc:
                    v=doc[k]
                    print(" has", k, type(v), (len(v) if hasattr(v,"__len__") else ""))
        else:
            print(" doc type", type(doc).__name__, str(doc)[:200])
    else:
        print(type(d), str(d)[:300])
